import sys
from typing import List, Tuple

def cross_product(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> int:
    return (a[0] - o[0]) * (b[1] - o[1]) - (a[1] - o[1]) * (b[0] - o[0])

def is_left_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, a, b) > 0

def is_right_turn(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, b, a) > 0

def is_collinear(o: Tuple[int, int], a: Tuple[int, int], b: Tuple[int, int]) -> bool:
    return cross_product(o, a , b) == 0

def is_intersection(a: Tuple[int, int], b: Tuple[int, int], c: Tuple[int, int], d: Tuple[int, int]) -> bool:
    if (is_collinear(a, b, c) and is_collinear(a, b, d)) or (is_collinear(c, d, a) and is_collinear(c, d, b)):
        return False
    return (cross_product(a, b, c) * cross_product(a, b, d) <= 0) and (cross_product(c, d, a) * cross_product(c, d, b) <= 0)

def find_permutation(n: int, points: List[Tuple[int, int]], s: str) -> List[int]:
    def dfs(u: int, path: List[int], visited: List[bool]) -> bool:
        if len(path) == n:
            return True
        for v in range(n):
            if not visited[v]:
                if len(path) >= 2:
                    if (s[len(path) - 2] == 'L' and is_left_turn(path[-2], path[-1], points[v])) or \
                       (s[len(path) - 2] == 'R' and is_right_turn(path[-2], path[-1], points[v])):
                        visited[v] = True
                        path.append(v)
                        if dfs(v, path, visited):
                            return True
                        path.pop()
                        visited[v] = False
                else:
                    visited[v] = True
                    path.append(v)
                    if dfs(v, path, visited):
                        return True
                    path.pop()
                    visited[v] = False
        return False

    for start in range(n):
        visited = [False] * n
        visited[start] = True
        path = [start]
        if dfs(start, path, visited):
            return [x + 1 for x in path]
    return []

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    points = []
    index = 1
    for _ in range(n):
        x = int(data[index])
        y = int(data[index + 1])
        points.append((x, y))
        index += 2

    s = data[-1]

    result = find_permutation(n, points, s)
    if result == []:
        print(-1)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
